export function canonical39SwitchDatabaseBytes(scenario: Canonical39SwitchScenario): Uint8Array {
  const fixture = canonical39SwitchFixtures[scenario];
  const recipe = readFileSync(new URL("./canonical39-switch-generator.original.ts.txt", import.meta.url));
  if (createHash("sha256").update(recipe).digest("hex") !== fixture.generatorSha256) {
    throw new Error("Canonical39 switch generator integrity mismatch.");
  }
  const bytes = gunzipSync(Buffer.from(compressedImages[scenario], "base64"), {
    maxOutputLength: fixture.databaseBytes,
  });
  if (bytes.length !== fixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== fixture.databaseSha256) {
    throw new Error("Canonical39 switch fixture integrity mismatch.");
  }
  return Uint8Array.from(bytes);
}
